% example of modeling a stiff differential equation% y' = a exp(at) (y-t)^2 + 1 % 0 < t < 1, y(0) = -1% choose: trapezoid, midpoint, AB2method = 'trapezoid';              a = 20;                      % transience parametery0 = -1;                     % initial valueMAXITER = 10000;             % maximum iterations for trapezoid                             % (need big for large h, but 10 works for small h)TOL = 10e-6;                 % tolerance for trapezoidMAXPLOT = 10;                % truncate plotfunction value = f(t,y,a)    % Octave likes the functions at the beginningvalue = a*exp(a*t)*(y-t)^2+1;%end                          %                             %function value = fy(t,y,a)   %value = 2*a*exp(a*t)*(y-t);  %end                          %T = 1;                       % final timet = linspace(0,T,1001);      % times to plot true solutionytrue = zeros(1,length(t));  % storage for true solutionytrue(1,1) = y0;for n=2:length(t)  ytrue(1,n) = t(n)-exp(-a*t(n));  enddisp(' ')disp('Hit return after each plot...')disp(' ')disp(method)disp(' ')disp('      h          error')for N = [5 10 20 50]  h = T/N;  tn = linspace(0,T,N+1);  Y = zeros(1,length(tn)); % storage for computed solution  Y(1,1) = y0;             % starting value  yn = y0;                 % starting value  for n = 1:N     switch method       case 'trapezoid'    % with Newton's method                    k1 = yn + 0.5*h*f(tn(n),yn,a);          w0 = k1;          j = 1;          FLAG = 0;                    while FLAG==0              w = w0 - ( w0 - 0.5*h*f(tn(n+1),w0,a) - k1 ) ...                       /( 1 - 0.5*h*fy(tn(n+1),w0,a) );              if abs(w-w0) < TOL                  FLAG = 1;                else                  j = j+1;                  w0 = w;                end              if j > MAXITER                  disp('Maximum iterations exceeded.')                  break                end          end                    ynp1 = w;                 case 'midpoint'          if n==1              ynp1 = yn + h*f(tn(n),yn,a);  % starting value (Euler)              ynm1 = yn;            else              ynp1 = yn + h*f( tn(n) + 0.5*h , yn + 0.5*h*f(tn(n),yn,a) , a);              ynm1 = yn;          end       case 'AB2'          if n==1              ynp1 = yn + h*f(tn(n),yn,a);  % starting value (Euler)              ynm1 = yn;            else              ynp1 = yn + 0.5*h*( 3*f(tn(n),yn,a) - f(tn(n-1),ynm1,a) );              ynm1 = yn;          end       end          if abs(ynp1) > MAXPLOT       % truncate plot       yn = sign(ynp1)*MAXPLOT;       Y(1,n+1) = yn;     else       yn = ynp1;       Y(1,n+1) = ynp1;     end     end  % error at time T:  err = Y(1,length(tn)) - ytrue(1,length(tn));  disp(sprintf('%10.5f   %10.4e',h,err))  % plot solution with this h:  plot(t,ytrue(1,:),'r')  hold on  plot(tn,Y(1,:),'bo-')  title(sprintf('%s method with h = %8.4f',method,h))  xlabel('t')  ylabel('y(t)')  hold off  % wait for user to hit return:  pause  end